#define SKIP_RUNTIME_CHECKS
// Verify: https://atcoder.jp/contests/math-and-algorithm/tasks/math_and_algorithm_bu

// Library: Geometry/geometory.cpp
// SPDX-License-Identifier: CC0-1.0
#include <algorithm>
#include <array>
#include <cmath>
#include <concepts>
#include <cstddef>
#include <cstdint>
