// SPDX-License-Identifier: CC0-1.0
#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>
#include <random>
template<class T,class C=geo::DefaultCalc<T>>void run(std::size_t n,int loops,int shape){
 std::vector<geo::Point<T,C>>v(n);std::mt19937_64 rng(17879);
 for(std::size_t i=0;i<n;++i){
  std::int64_t x=i<n/2?std::int64_t(i):std::int64_t(n-1-i),y=i<n/2?1000000:-1000000;
  if(shape==1)y+=std::int64_t(rng()%500001);
  if(shape==2)y+=2000000;
  if(shape==3){y=std::int64_t(i%2)*2000000-1000000;}
  if(shape==4){y=std::int64_t(i<n/2?1:-1)*(100000+std::int64_t(rng()%1000000));}
  if(shape==5){x=std::int64_t(rng()%2000001)-1000000;y=std::int64_t(rng()%2000001)-1000000;}
  if(shape==6){x*=100000000;y*=1000000;}
  v[i]={T(x),T(y)};
 }
 std::int64_t checksum=0;auto start=std::chrono::steady_clock::now();
 for(int k=0;k<loops;++k){geo::Point<T,C>q{T(std::int64_t(n/3)+k%17),T(k%7-3)};if(shape==7)q.y=T(1000000);checksum+=static_cast<int>(geo::contains(v,q));}
 auto end=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(end-start).count()<<' '<<checksum<<'\n';
}
int main(int argc,char**argv){if(argc!=6)return 1;auto n=std::strtoull(argv[1],nullptr,10);int loops=std::atoi(argv[2]),shape=std::atoi(argv[3]);std::string type=argv[4],c=argv[5];if(type=="integer"&&c=="default")run<std::int64_t>(n,loops,shape);else if(type=="integer")run<std::int64_t,std::int64_t>(n,loops,shape);else if(type=="double")run<double>(n,loops,shape);else run<long double>(n,loops,shape);}

