from pathlib import Path
p=Path(__file__).parent;s=(p/'simd_gate.hpp').read_text()
helper=r'''
template<class C>
__attribute__((noinline))
geo::Location contains_scalar_resume(const std::vector<geo::Point<std::int64_t,C>>& poly,const geo::Point<std::int64_t,C>& p,geo::Epsilon eps,std::size_t first,std::int64_t winding) {
    for(std::size_t i=first;i<poly.size();++i) {
        const auto& a=poly[i];const auto& b=poly[i+1==poly.size()?0:i+1];
        if((a.y<p.y && b.y<p.y) || (a.y>p.y && b.y>p.y))continue;
        int side=geo::orientation(a,b,p,eps);
        if(side==0 && std::min(a.x,b.x)<=p.x && p.x<=std::max(a.x,b.x) && std::min(a.y,b.y)<=p.y && p.y<=std::max(a.y,b.y))return geo::Location::Boundary;
        if(a.y<=p.y && p.y<b.y && side>0)++winding;
        if(b.y<=p.y && p.y<a.y && side<0)--winding;
    }
    return winding?geo::Location::Inside:geo::Location::Outside;
}
'''
s=s.replace('namespace reinsirk::detail {\ntemplate<class C>\n__attribute__((target', 'namespace reinsirk::detail {\n'+helper+'\ntemplate<class C>\n__attribute__((target')
s=s.replace('std::size_t aindex=0,i=1;','std::size_t aindex=0,i=1;\n    unsigned failures=0;')
s=s.replace('aindex=i+3;i+=4;continue;','aindex=i+3;i+=4;failures=0;continue;')
s=s.replace('        const std::size_t end=i+4;','''        if(++failures==2)return contains_scalar_resume(poly,p,eps,aindex,winding);
        const std::size_t end=i+4;''')
(p/'simd_resume.hpp').write_text(s)
b=(p/'bench.cpp').read_text().replace('  v[i]={T(x),T(y)};','  if(shape==8)y=i<9?1000000:(i%2?1000000:-1000000);\n  v[i]={T(x),T(y)};')
(p/'bench_resume.cpp').write_text(b)

