from pathlib import Path
import subprocess,json,fcntl,statistics
p=Path(__file__).parent;variants=['baseline','halfopen','simd'];d={'status':'INCOMPLETE','builds':[],'api':{}}
for mode,cc in {'gcc':['/usr/bin/g++'],'gcc_native':['/usr/bin/g++','-march=native'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']}.items():
 for v in variants:
  cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'bench.cpp'),'-o',str(p/(mode+'_'+v))];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,(cmd,q.stderr);d['builds'].append(cmd)
 print('compiled',mode,flush=True)
with open('/tmp/sirkit_performance_cpu14.lock','a')as a,open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as b:
 fcntl.flock(a,fcntl.LOCK_EX);fcntl.flock(b,fcntl.LOCK_EX)
 for mode in ['gcc','gcc_native','clang']:
  d['api'][mode]={}
  cases=[(4,200000,0,'integer','default'),(32,30000,1,'integer','default'),(4096,300,1,'integer','default'),*[(524288,4,s,'integer','default')for s in range(8)],(524288,4,4,'integer','int64'),(524288,4,1,'double','default')]
  for n,loops,shape,t,c in cases:
   raw={v:[]for v in variants};checksum=None
   for rep in range(5):
    for v in variants[rep%len(variants):]+variants[:rep%len(variants)]:
     out=subprocess.check_output(['taskset','-c','14',str(p/(mode+'_'+v)),str(n),str(loops),str(shape),t,c]).decode().split();raw[v].append(float(out[0]));check=out[1]
     if checksum is None:checksum=check
     assert check==checksum,(mode,n,shape,t,c,v,check,checksum)
   med={v:statistics.median(x)for v,x in raw.items()};ratios={v:x/med['halfopen']for v,x in med.items()};d['api'][mode][f'{n}/{shape}/{t}/{c}']={'raw_ms':raw,'medians_ms':med,'ratios_vs_halfopen':ratios,'loops':loops,'checksum':checksum};print(mode,n,shape,t,c,{v:round(x,3)for v,x in ratios.items()},flush=True)
d['status']='PASS';(p/'performance.json').write_text(json.dumps(d,indent=2)+'\n')

