namespace reinsirk::detail {
template<class C>
__attribute__((target("avx2")))
geo::Location contains_avx2(const std::vector<geo::Point<std::int64_t,C>>& poly, const geo::Point<std::int64_t,C>& p, geo::Epsilon eps) {
    using P=geo::Point<std::int64_t,C>;
    static_assert(sizeof(P)==16 && offsetof(P,y)==8);
    std::int64_t winding=0;
    std::size_t aindex=0,i=1;
    const auto py=_mm256_set1_epi64x(p.y);
    auto step=[&](const P& a,const P& b) {
        if((a.y<p.y && b.y<p.y) || (a.y>p.y && b.y>p.y))return false;
        int side=geo::orientation(a,b,p,eps);
        if(side==0 && std::min(a.x,b.x)<=p.x && p.x<=std::max(a.x,b.x) && std::min(a.y,b.y)<=p.y && p.y<=std::max(a.y,b.y))return true;
        if(a.y<=p.y && p.y<b.y && side>0)++winding;
        if(b.y<=p.y && p.y<a.y && side<0)--winding;
        return false;
    };
    for(;i+3<poly.size();) {
        auto v0=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(poly.data()+i));
        auto v1=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(poly.data()+i+2));
        auto ys=_mm256_permute4x64_epi64(_mm256_unpackhi_epi64(v0,v1),_MM_SHUFFLE(3,1,2,0));
        const unsigned above=unsigned(_mm256_movemask_pd(_mm256_castsi256_pd(_mm256_cmpgt_epi64(ys,py))));
        const unsigned equal=unsigned(_mm256_movemask_pd(_mm256_castsi256_pd(_mm256_cmpeq_epi64(ys,py))));
        if((above==15 && poly[aindex].y>p.y) || (above==0 && equal==0 && poly[aindex].y<p.y)) {
            aindex=i+3;i+=4;continue;
        }
        if(i<=5) {
            const bool early_second = i==5;
            if(early_second) return geo::contains_original(poly,p,eps);
        }
        const std::size_t end=i+4;
        for(;i<end;++i) {
            if(step(poly[aindex],poly[i]))return geo::Location::Boundary;
            aindex=i;
        }
    }
    for(;i<poly.size();++i) {
        if(step(poly[aindex],poly[i]))return geo::Location::Boundary;
        aindex=i;
    }
    if(step(poly[aindex],poly[0]))return geo::Location::Boundary;
    return winding?geo::Location::Inside:geo::Location::Outside;
}
}
#endif
namespace geo {
template<class T,class C> Location contains(const std::vector<Point<T,C>>& poly,const Point<T,C>& p,Epsilon eps={}) {
#if !defined(SIRKIT_DISABLE_SIMD) && (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__))
    if constexpr(std::is_same_v<T,std::int64_t> && std::numeric_limits<C>::is_integer) {
        if(poly.size()>=256) {
            static const bool available=__builtin_cpu_supports("avx2");
            if(available)return reinsirk::detail::contains_avx2(poly,p,eps);
        }
    }
#endif
    return contains_scalar(poly,p,eps);
}
}

