#if !defined(SIRKIT_DISABLE_SIMD) && (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__))
#include <immintrin.h>
namespace reinsirk::detail {

template<class C>
__attribute__((noinline))
geo::Location contains_scalar_resume(const std::vector<geo::Point<std::int64_t,C>>& poly,const geo::Point<std::int64_t,C>& p,geo::Epsilon eps,std::size_t first,std::int64_t winding) {
    for(std::size_t i=first;i<poly.size();++i) {
        const auto& a=poly[i];const auto& b=poly[i+1==poly.size()?0:i+1];
        if((a.y<p.y && b.y<p.y) || (a.y>p.y && b.y>p.y))continue;
        int side=geo::orientation(a,b,p,eps);
        if(side==0 && std::min(a.x,b.x)<=p.x && p.x<=std::max(a.x,b.x) && std::min(a.y,b.y)<=p.y && p.y<=std::max(a.y,b.y))return geo::Location::Boundary;
        if(a.y<=p.y && p.y<b.y && side>0)++winding;
        if(b.y<=p.y && p.y<a.y && side<0)--winding;
    }
    return winding?geo::Location::Inside:geo::Location::Outside;
}

template<class C>
__attribute__((target("avx2")))
geo::Location contains_avx2(const std::vector<geo::Point<std::int64_t,C>>& poly, const geo::Point<std::int64_t,C>& p, geo::Epsilon eps) {
    using P=geo::Point<std::int64_t,C>;
    static_assert(sizeof(P)==16 && offsetof(P,y)==8);
    std::int64_t winding=0;
    std::size_t aindex=0,i=1;
    unsigned failures=0;
    const auto py=_mm256_set1_epi64x(p.y);
    auto step=[&](const P& a,const P& b) {
        if(a.y==p.y) {
            if(a.x==p.x) return true;
            if(b.y==p.y && std::min(a.x,b.x)<=p.x && p.x<=std::max(a.x,b.x))return true;
        }
        bool above=a.y>p.y,next=b.y>p.y;
        if(above!=next) {
            const int side=geo::orientation(a,b,p,eps);
            if(side==0)return true;
            if(next)winding+=side>0;else winding-=side<0;
        }
        return false;
    };
    for(;i+3<poly.size();) {
        auto v0=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(poly.data()+i));
        auto v1=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(poly.data()+i+2));
        auto ys=_mm256_permute4x64_epi64(_mm256_unpackhi_epi64(v0,v1),_MM_SHUFFLE(3,1,2,0));
        const unsigned above=unsigned(_mm256_movemask_pd(_mm256_castsi256_pd(_mm256_cmpgt_epi64(ys,py))));
        const unsigned equal=unsigned(_mm256_movemask_pd(_mm256_castsi256_pd(_mm256_cmpeq_epi64(ys,py))));
        if((above==15 && poly[aindex].y>p.y) || (above==0 && equal==0 && poly[aindex].y<p.y)) {
            aindex=i+3;i+=4;failures=0;continue;
        }
        if(++failures==2)return contains_scalar_resume(poly,p,eps,aindex,winding);
        const std::size_t end=i+4;
        for(;i<end;++i) {
            if(step(poly[aindex],poly[i]))return geo::Location::Boundary;
            aindex=i;
        }
    }
    for(;i<poly.size();++i) {
        if(step(poly[aindex],poly[i]))return geo::Location::Boundary;
        aindex=i;
    }
    if(step(poly[aindex],poly[0]))return geo::Location::Boundary;
    return winding?geo::Location::Inside:geo::Location::Outside;
}
}
#endif
namespace geo {
template<class T,class C> Location contains(const std::vector<Point<T,C>>& poly,const Point<T,C>& p,Epsilon eps={}) {
#if !defined(SIRKIT_DISABLE_SIMD) && (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__))
    if constexpr(std::is_same_v<T,std::int64_t> && std::numeric_limits<C>::is_integer) {
        if(poly.size()>=256) {
            const bool upper=poly[0].y>p.y;
            bool same=poly[0].y!=p.y;
            for(std::size_t i=1;i<=8 && same;++i) same=upper ? poly[i].y>p.y : poly[i].y<p.y;
            if(same) {
                static const bool available=__builtin_cpu_supports("avx2");
                if(available)return reinsirk::detail::contains_avx2(poly,p,eps);
            }
        }
    }
#endif

    if (poly.empty()) return Location::Outside;
    if (poly.size() == 1) return on_segment(p, Segment<T, C>{poly[0], poly[0]}, eps) ? Location::Boundary : Location::Outside;
    std::int64_t winding = 0;
    for (std::size_t i = 0; i < poly.size(); ++i) {
        const auto& a = poly[i];
        const auto& b = poly[i + 1 == poly.size() ? 0 : i + 1];
        if constexpr (std::is_integral_v<T>) {
            if ((a.y < p.y && b.y < p.y) || (a.y > p.y && b.y > p.y)) continue;
        }
        int side = orientation(a, b, p, eps);
        if (side == 0) {
            if constexpr (std::is_integral_v<T>) {
                if (std::min(a.x, b.x) <= p.x && p.x <= std::max(a.x, b.x) &&
                    std::min(a.y, b.y) <= p.y && p.y <= std::max(a.y, b.y)) return Location::Boundary;
            } else if (on_segment(p, Segment<T, C>{a, b}, eps)) return Location::Boundary;
        }
        if (a.y <= p.y && p.y < b.y && side > 0) ++winding;
        if (b.y <= p.y && p.y < a.y && side < 0) --winding;
    }
    return winding != 0 ? Location::Inside : Location::Outside;

}
}

