        {{2, 2}, {2, 2}}, {{0, 0}, {8, 0}, {8, 8}, {0, 8}},
        {{0, 4}, {4, 0}, {8, 4}, {4, 8}}, {{0, 0}, {8, 2}, {4, 8}},
        {{0, 0}, {8, 0}, {8, 2}, {2, 2}, {2, 8}, {0, 8}},
        {{0, 0}, {8, 0}, {8, 8}, {6, 8}, {6, 2}, {2, 2}, {2, 8}, {0, 8}},
